class LinkShortener {
  private urls: string[] = [];
  private links: string[] = [];

  private code(k: number): string {
    const A = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
    let s = "";
    do { s = A[k % 62] + s; k = Math.floor(k / 62); } while (k > 0);
    return s;
  }

  shorten(longUrl: string): string {
    const i = this.urls.indexOf(longUrl);
    if (i >= 0) return this.links[i];
    this.urls.push(longUrl);
    const link = "https://sho.rt/" + this.code(this.urls.length);
    this.links.push(link);
    return link;
  }

  expand(shortUrl: string): string {
    const i = this.links.indexOf(shortUrl);
    return i >= 0 ? this.urls[i] : "";
  }
}

